import {marked} from './vendor/marked.js';
import {mountScene,mountBell} from './labs/foundations.js';
import {mountPlane,mountCovariance} from './labs/plane.js';
import {mountEditor} from './labs/editor.js';
import {mountLoss,mountDescent,mountAutograd,mountFitting} from './labs/learning.js';
import {blocks,names,descriptions,lessonNumbers,blockForLesson,pad,parseRoute} from './curriculum.js';

const main=document.querySelector('#main'),side=document.querySelector('#sidebar');
const mounts={scene:mountScene,bell:mountBell,plane:mountPlane,covariance:mountCovariance,editor:mountEditor,loss:mountLoss,descent:mountDescent,autograd:mountAutograd,fitting:mountFitting};
const states={},cache={};let activeLabs=[],observer,heroCleanup=()=>{},routeNumber=0,lang='ru',routeSerial=0;
const tx=(ru,en)=>lang==='ru'?ru:en;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};

function prose(source){
  const stash=[];
  const token=(tex,display)=>{const i=stash.push({tex,display})-1;return display?`\n\n<div class="math-display" data-math="${i}"></div>\n\n`:`<span class="math-inline" data-math="${i}"></span>`};
  // Protect TeX before Markdown sees '=' lines or '|' inside a matrix.
  source=source.replace(/(```[\s\S]*?```|`[^`\n]*`)|(\$\$([\s\S]*?)\$\$)|(\$([^$\n]+)\$)/g,(m,code,block,btex,inline,itex)=>code||token(btex??itex,!!block));
  const div=document.createElement('div');div.className='article-prose';div.innerHTML=marked.parse(source,{gfm:true});
  div.querySelectorAll('[data-math]').forEach(node=>{const item=stash[+node.dataset.math];try{window.katex.render(item.tex.trim(),node,{displayMode:item.display,throwOnError:true,strict:'ignore',trust:false,output:'htmlAndMathml'})}catch(error){node.textContent=item.tex;node.classList.add('math-error');console.error(error)}node.removeAttribute('data-math')});
  div.querySelectorAll('table').forEach(table=>{const wrap=document.createElement('div');wrap.className='table-scroll';table.before(wrap);wrap.append(table)});
  div.querySelectorAll('a[href^="http"]').forEach(a=>{a.target='_blank';a.rel='noopener'});
  return div;
}
function codeBlock(cell){const details=document.createElement('details');details.className='code-block';details.dataset.language='Python';const sum=document.createElement('summary');sum.textContent=tx('Код и расчёт','Code and calculation');details.append(sum);const content=document.createElement('div');content.className='code-content';const pre=document.createElement('pre'),code=document.createElement('code');code.textContent=cell.source;pre.append(code);content.append(pre);const copy=document.createElement('button');copy.className='copy-code';copy.type='button';copy.textContent=tx('Копировать','Copy');copy.onclick=async()=>{try{await navigator.clipboard.writeText(cell.source);copy.textContent=tx('Скопировано','Copied')}catch{copy.textContent=tx('Копирование недоступно','Copy unavailable')}setTimeout(()=>copy.textContent=tx('Копировать','Copy'),1600)};content.append(copy);if(cell.output){const out=document.createElement('pre');out.className='output';out.setAttribute('aria-label',tx('Результат Python','Python output'));out.textContent=cell.output;content.append(out)}details.append(content);return details}

function browserCode(name){
 const file={scene:'foundations',bell:'foundations',plane:'plane',covariance:'plane',editor:'editor',loss:'learning',descent:'learning',autograd:'learning',fitting:'learning'}[name];
 const details=document.createElement('details');details.className='code-block browser-code';details.dataset.language='JavaScript';
 const summary=document.createElement('summary');summary.textContent=tx('Как устроена демонстрация','Inside the experiment');details.append(summary);
 let loaded=false;details.addEventListener('toggle',async()=>{if(!details.open||loaded)return;loaded=true;const content=document.createElement('div');content.className='code-content';const pre=document.createElement('pre');pre.textContent=tx('Загрузка…','Loading…');content.append(pre);details.append(content);try{const response=await fetch(`labs/${file}.js`);if(!response.ok)throw Error();pre.textContent=await response.text()}catch{pre.textContent=tx('Исходник доступен по ссылке ниже.','The source is available at the link below.')}const link=document.createElement('a');link.className='quiet-button';link.href=`labs/${file}.js`;link.target='_blank';link.rel='noopener';link.textContent=tx('Полный исходник ↗','Full source ↗');content.append(link)});return details;
}

function miniArt(i){const colors=['#4257d8','#eb8d55','#8eaa69'];let marks='';if(i===1){for(let n=0;n<24;n++){const a=n*2.39996,r=Math.sqrt(n/24)*24;marks+=`<ellipse cx="${65+Math.cos(a)*r}" cy="${30+Math.sin(a)*r}" rx="10" ry="5" fill="${colors[n%3]}" opacity=".35" transform="rotate(-25 ${65+Math.cos(a)*r} ${30+Math.sin(a)*r})"/>`}}else if(i===2){marks='<path d="M7 51 C35 51 39 49 50 28 C62 3 68 3 79 28 C90 49 95 51 123 51" fill="none" stroke="#4c61d5" stroke-width="2"/><path d="M7 51H123" stroke="#b6c1a3"/><path d="M66 6V54" stroke="#c8d1bb" stroke-dasharray="3"/>'}else if(i===5){marks='<ellipse cx="53" cy="31" rx="27" ry="17" fill="#ef8754" opacity=".55"/><ellipse cx="77" cy="31" rx="27" ry="17" fill="#596ee6" opacity=".55"/>'}else if(i===6){for(let row=0;row<3;row++)for(let col=0;col<5;col++)marks+=`<rect x="${18+col*19}" y="${7+row*18}" width="15" height="14" rx="2" fill="${(row+col)%3?'#dde2ce':'#db7960'}"/>`}else if(i===7){marks='<path d="M13 9 Q64 100 117 10" fill="none" stroke="#819470" stroke-width="2"/><path d="M27 29L45 48L58 53" fill="none" stroke="#445ada" stroke-width="2"/><circle cx="27" cy="29" r="4" fill="#e48c5d"/><circle cx="58" cy="53" r="4" fill="#445ada"/>'}else if(i===8){marks='<path d="M24 33H106" stroke="#9aa98a" stroke-width="2"/>';for(let n=0;n<4;n++)marks+=`<circle cx="${20+n*30}" cy="33" r="10" fill="${n===3?'#5a6dd3':'#e5e9da'}" stroke="#9aa98a"/>`}else if(i===9){for(let n=0;n<18;n++)marks+=`<ellipse cx="${24+(n%6)*16}" cy="${15+Math.floor(n/6)*17}" rx="12" ry="9" fill="${colors[n%3]}" opacity=".45"/>`}else{for(let r=1;r<=4;r++)marks+=`<ellipse cx="65" cy="32" rx="${r*13}" ry="${r*5.6}" transform="rotate(${i===4?-32:0} 65 32)" fill="none" stroke="#${i===4?'657ac4':'88a46d'}" opacity="${1-r*.14}"/>`}return `<svg class="row-art" viewBox="0 0 130 65" aria-hidden="true">${marks}</svg>`}
function sidebar(){
 side.innerHTML=`<a class="side-home" href="#/${lang}">← ${tx('Весь курс','Course overview')}</a>${blocks.map(block=>`<section class="side-block"><p class="side-label">${tx('Блок','Block')} ${pad(block.number)} · ${block.short[lang]}</p>${block.lessons.map(number=>`<a class="side-lesson ${routeNumber===number?'active':''}" href="#/${lang}/${number}" ${routeNumber===number?'aria-current="page"':''}><span class="side-num">${pad(number)}</span><span class="side-title">${names[lang][number-1]}</span></a>`).join('')}</section>`).join('')}<div class="side-foot">${tx('Картинка → числа → формула.','Image → numbers → formula.')}<br>Heinrich Wirth<br><a href="https://github.com/HeinrichWirth/gaussian-splatting-course" target="_blank" rel="noopener">${tx('Материалы и исходники','Materials and source')} ↗</a></div>`;
 document.querySelector('.brand').href=`#/${lang}`;
 document.querySelector('.topbar-caption').textContent=tx('Интерактивный курс · От формы к обучению','Interactive course · From shape to learning');
 const toggle=document.querySelector('#language');toggle.textContent=lang==='ru'?'EN':'RU';toggle.setAttribute('aria-label',lang==='ru'?'Switch to English':'Переключить на русский');toggle.onclick=()=>{location.hash=`#/${lang==='ru'?'en':'ru'}${routeNumber?'/'+routeNumber:''}`};document.querySelector('#menu').setAttribute('aria-label',tx('Меню уроков','Lesson menu'));
}
function blockCards(){return blocks.map(block=>`<section class="course-block" id="block-${block.number}"><div class="section-heading"><h2>${block.title[lang]}</h2><span>${tx('Блок','Block')} ${pad(block.number)}</span></div><p class="block-description">${block.description[lang]}</p>${block.lessons.map(number=>`<a class="lesson-row" href="#/${lang}/${number}"><span class="row-number">${pad(number)}</span><div><div class="row-title">${names[lang][number-1]}</div><div class="row-desc">${descriptions[lang][number-1]}</div></div>${miniArt(number)}<span class="row-arrow">↗</span></a>`).join('')}</section>`).join('')}
function home(){main.className='home-page';main.innerHTML=`<div class="home-wrap"><section class="hero"><div class="hero-text"><div class="eyebrow">${tx('Gaussian Splatting — изнутри','Gaussian Splatting — from within')}</div><h1>${tx('Из пятен —<br><em>в картинку.</em>','From splats<br><em>to an image.</em>')}</h1><p class="hero-copy">${tx('У мягкого цветного пятна есть своя математика. Здесь она начинается с картинки и разбирается до последнего действия.','A soft patch of color has its own mathematics. Here it starts with an image and unfolds one operation at a time.')}</p><a class="hero-cta" href="#/${lang}/1">${tx('Первый урок','First lesson')} <span>↗</span></a></div><div class="hero-visual"><canvas id="hero-canvas" width="900" height="900" aria-label="${tx('Цветная сфера, собранная из мягких гауссиан','A colored sphere assembled from soft Gaussians')}"></canvas><span class="hero-chip">192 SPLATS / ONE SCENE</span></div></section><div class="intro-strip"><div class="intro-item"><small>01 /</small><strong>${tx('Сначала видно','Visible first')}</strong><p>${tx('Параметр меняется — картинка отвечает.','A parameter changes. The image responds.')}</p></div><div class="intro-item"><small>02 /</small><strong>${tx('Математика по шагам','Math, one step at a time')}</strong><p>${tx('Каждый символ, действие и подстановка.','Every symbol, operation, and substitution.')}</p></div><div class="intro-item"><small>03 /</small><strong>${tx('Код рядом','Code alongside')}</strong><p>${tx('Python с расчётами — под объяснением.','Python calculations beside the explanation.')}</p></div></div>${blockCards()}<footer class="home-footer"><span>Heinrich Wirth · Gaussian Splatting</span><a href="https://github.com/HeinrichWirth/gaussian-splatting-course" target="_blank" rel="noopener">${tx('Полный план курса','Full course plan')} ↗</a></footer></div>`;heroCleanup=drawHero(document.querySelector('#hero-canvas'))}
function drawHero(canvas){const ctx=canvas.getContext('2d');let mx=0,my=0;function draw(){ctx.clearRect(0,0,900,900);ctx.save();ctx.translate(450,450);ctx.strokeStyle='#d5ddc7';ctx.lineWidth=1;for(const r of [240,310,380]){ctx.beginPath();ctx.ellipse(0,60,r,r*.36,-.35,0,Math.PI*2);ctx.stroke()}ctx.restore();const points=[];for(let i=0;i<192;i++){const z=1-2*(i+.5)/192,a=i*2.399963,r=Math.sqrt(1-z*z),x=r*Math.cos(a),y=r*Math.sin(a),angle=.7+mx*.3,xx=x*Math.cos(angle)-y*Math.sin(angle),yy=x*Math.sin(angle)+y*Math.cos(angle),zz=z;points.push({x:450+xx*260,y:430+(zz*.92+yy*.25+my*xx*.15)*-260,depth:yy,color:`hsl(${213+zz*38+xx*90},${65+yy*10}%,${55+yy*9}%)`,angle:a})}points.sort((a,b)=>a.depth-b.depth);for(const p of points){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.scale(1.65,.78);const g=ctx.createRadialGradient(0,0,0,0,0,34);g.addColorStop(0,p.color);g.addColorStop(.27,p.color.replace('hsl','hsla').replace('%)','%, .66)'));g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.globalAlpha=.88;ctx.fillRect(-35,-35,70,70);ctx.restore()}}draw();let frame=0;const move=e=>{const rect=canvas.getBoundingClientRect();mx=(e.clientX-rect.left)/rect.width-.5;my=(e.clientY-rect.top)/rect.height-.5;if(!frame)frame=requestAnimationFrame(()=>{frame=0;draw()})};canvas.addEventListener('pointermove',move);return()=>{cancelAnimationFrame(frame);canvas.removeEventListener('pointermove',move)}}
async function lesson(number,serial){if(!cache[lang]){const response=await fetch(`content/${lang}.json`);if(!response.ok)throw Error('Lesson content unavailable');cache[lang]=await response.json()}if(serial!==routeSerial)return;const lesson=cache[lang][number-1];main.className='lesson-page';main.innerHTML=`<div class="lesson-layout"><article class="lesson-article"><header class="lesson-header"><div class="eyebrow">${tx('Блок','Block')} ${pad(blockForLesson(number).number)} · ${tx('Урок','Lesson')} ${pad(number)}</div><h1>${escape(lesson.title.replace(/^(Урок|Lesson)\s*\d+\s*[.·:—–-]?\s*/i,''))}</h1><div class="lesson-meta"><span>${tx('Живая демонстрация','Live experiment')}</span><span>${tx('Подробный разбор','Step-by-step math')}</span><span>Python</span></div><div class="lesson-tools"><button type="button" class="quiet-button" id="jump-lab">${tx('К демонстрации','To the experiment')} ↓</button><button type="button" class="quiet-button" id="toggle-code">${tx('Показать весь код','Show all code')}</button></div></header><div id="lesson-content"></div><nav class="lesson-nav"></nav><a class="source-link" href="${lesson.source}" target="_blank" rel="noopener">${tx('Исходный ноутбук и Python-модули','Original notebook and Python modules')} ↗</a></article><aside class="outline" aria-label="${tx('Содержание урока','Lesson contents')}"><div class="outline-label">${tx('В этом уроке','In this lesson')}</div></aside></div>`;
 const content=document.querySelector('#lesson-content');for(const cell of lesson.cells){if(cell.type==='text')content.append(prose(cell.source));else if(cell.type==='code')content.append(codeBlock(cell));else if(cell.type==='image'){const f=document.createElement('figure');f.className='figure';f.innerHTML=`<img src="${cell.src}" loading="lazy" alt="${tx('Схема к разбору','Diagram for the explanation')}: ${escape(names[lang][number-1])}">`;content.append(f)}else if(cell.type==='lab'){const host=document.createElement('div');host.id='experiment';content.append(host);const instance=mounts[cell.name](host,lang,states[cell.name]||{});activeLabs.push({name:cell.name,instance});content.append(browserCode(cell.name))}}
 const headings=[...content.querySelectorAll('h2')],outline=document.querySelector('.outline');headings.forEach((h,i)=>{h.id='section-'+i;const a=document.createElement('a');a.href='#'+h.id;a.textContent=h.textContent.replace(/^\d+[.\s]+/,'');a.onclick=e=>{e.preventDefault();h.scrollIntoView({behavior:'smooth'});history.replaceState(null,'',`#/${lang}/${number}?s=${i}`)};outline.append(a)});
 observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){outline.querySelectorAll('a').forEach(a=>a.classList.toggle('current',a.getAttribute('href')==='#'+entry.target.id))}},{rootMargin:'-90px 0px -65% 0px'});headings.forEach(h=>observer.observe(h));
 document.querySelector('#jump-lab').onclick=()=>document.querySelector('#experiment').scrollIntoView({behavior:'smooth',block:'start'});let expanded=false;document.querySelector('#toggle-code').onclick=e=>{expanded=!expanded;content.querySelectorAll('.code-block').forEach(b=>b.open=expanded);e.target.textContent=expanded?tx('Свернуть весь код','Collapse all code'):tx('Показать весь код','Show all code')};
 const nav=document.querySelector('.lesson-nav');nav.innerHTML=`<a href="#/${lang}${number>1?'/'+(number-1):''}"><small>← ${tx('Назад','Previous')}</small><strong>${number>1?names[lang][number-2]:tx('Весь курс','Course overview')}</strong></a><a href="#/${lang}${number<lessonNumbers.length?'/'+(number+1):''}"><small>${tx(number<lessonNumbers.length?'Следующий урок':'К программе курса',number<lessonNumbers.length?'Next lesson':'Course overview')} →</small><strong>${number<lessonNumbers.length?names[lang][number]:tx('От изображения — к обучению','From an image to learning')}</strong></a>`;
 document.title=`${names[lang][number-1]} — Gaussian Splatting`;const section=new URLSearchParams(location.hash.split('?')[1]||'').get('s');if(section!==null)document.querySelector('#section-'+Number(section))?.scrollIntoView();storage.set('gs-last-lesson',String(number));
}
function cleanup(){for(const {name,instance}of activeLabs){states[name]=instance.getState();if(name==='editor')storage.set('gs-editor',JSON.stringify(states[name]));instance.destroy()}activeLabs=[];observer?.disconnect();heroCleanup();heroCleanup=()=>{}}
async function route(){const serial=++routeSerial;cleanup();const parsed=parseRoute(location.hash);lang=parsed.language||(storage.get('gs-language')||'ru');routeNumber=parsed.number;if(!['ru','en'].includes(lang))lang='ru';storage.set('gs-language',lang);document.documentElement.lang=lang;side.classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');sidebar();window.scrollTo(0,0);try{if(routeNumber)await lesson(routeNumber,serial);else{home();document.title=tx('Gaussian Splatting — изнутри','Gaussian Splatting — from within')}}catch(error){main.innerHTML=`<div class="empty-state"><h1>${tx('Не удалось открыть урок','The lesson could not be opened')}</h1><p>${tx('Материалы также доступны в','Materials are also available in the')} <a href="https://github.com/HeinrichWirth/gaussian-splatting-course">GitHub</a>.</p><button class="quiet-button" onclick="location.reload()">${tx('Повторить','Retry')}</button></div>`;console.error(error)}updateProgress()}
function updateProgress(){const height=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress i').style.width=routeNumber&&height>0?`${100*scrollY/height}%`:'0'}
document.querySelector('.skip-link').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};window.addEventListener('hashchange',route);window.addEventListener('scroll',updateProgress,{passive:true});window.addEventListener('beforeunload',()=>{for(const {name,instance}of activeLabs)if(name==='editor')storage.set('gs-editor',JSON.stringify(instance.getState()))});try{const saved=storage.get('gs-editor');if(saved)states.editor=JSON.parse(saved)}catch{}
document.querySelector('#menu').onclick=e=>{const open=side.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))};window.addEventListener('keydown',e=>{if(e.key==='Escape'){side.classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')}});
route();
